import {renderExpertToolCard,renderToolDirectory,renderOddsTool} from './expert-tools.js';
import {EDITORIAL_COVERS,renderColumnsPage,normalizeEditorialFields,editorialFieldsMarkup,renderSearchPreview,renderArticleBody,articleOutline,renderArticleNext,articleMeta,publicColumns,editorialCover} from './editorial.js';

import {findResponsibleArticle,renderResponsibleHub,renderResponsibleArticle,renderResponsibleReminder} from './responsible-gaming.js';

const $ = s => document.querySelector(s);
const e = escapeHtml;
let state;
try { state = restoreState(JSON.parse(localStorage.getItem(STORAGE_KEY))); } catch { state = initialState(); }
let feedTab = 'latest', sport = '全部', contentType = '全部', search = '', matchTab = 'data', expertTab = '全部', dateFilter = '10/26';
let modalState = null, pendingAction = null, toastTimer;
let oddsToolMatch='m1',oddsToolValues=null;
let columnQuery='',columnSport='全部',columnExpert='all';
let rgQuery='',rgCategory='全部';
const scrollMemory = new Map(); let displayedRoute=location.hash.slice(1)||'/';
window.addEventListener('scroll',()=>scrollMemory.set(displayedRoute,window.scrollY),{passive:true});
const nav = [['/','首頁','home'],['/matches','賽事中心','calendar'],['/community','討論區','message'],['/experts','專家廣場','users'],['/columns','公開專欄','book'],['/tools','專家工具','chart'],['/learn','新手學堂','book'],['/responsible-gaming','責任博彩','shield'],['/inbox','會員互動','message']];
