  trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',
  filter:'M4 6h16M7 12h10m-7 6h4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  baseball:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M5 5c7 2 7 12 0 14M19 5c-7 2-7 12 0 14',
  basketball:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2v20M5 5c7 2 7 12 0 14M19 5c-7 2-7 12 0 14',
  crown:'m3 6 4 5 5-7 5 7 4-5-2 13H5Z',more:'M5 12h.01M12 12h.01M19 12h.01',
